actions:
  pay_order:
    method: POST
    path: /orders/{id}/pay
    description: Mark a pending order as paid.
    input: {}
    handler: |-
      (ctx) => {
        const id = ctx.params.id;
        const o = ctx.db.get('order', id);
        if (o === null) ctx.fail(404, 'not_found', 'order ' + id + ' not found');
        if (o.status !== 'pending') ctx.fail(409, 'invalid_state', 'order ' + id + ' is ' + o.status + '. Only pending orders can be paid.');
        const updated = ctx.db.update('order', id, { status: 'paid' });
        ctx.db.create('order_event', { order_id: id, kind: 'paid', note: null });
        return { status: 200, body: updated };
      }
  ship_order:
    method: POST
    path: /orders/{id}/ship
    description: Ship a paid order, stamping shipped_at and optional tracking number.
    input:
      tracking_number:
        type: string
        description: Optional carrier tracking number.
        required: false
        nullable: true
        unique: false
        readonly: false
        maxLength: 60
    handler: |-
      (ctx) => {
        const id = ctx.params.id;
        const o = ctx.db.get('order', id);
        if (o === null) ctx.fail(404, 'not_found', 'order ' + id + ' not found');
        if (o.status !== 'paid') ctx.fail(409, 'invalid_state', 'order ' + id + ' is ' + o.status + '. Only paid orders can be shipped.');
        const tn = ctx.body.tracking_number === undefined ? null : ctx.body.tracking_number;
        const updated = ctx.db.update('order', id, { status: 'shipped', shipped_at: ctx.now(), tracking_number: tn });
        ctx.db.create('order_event', { order_id: id, kind: 'shipped', note: tn === null ? null : 'tracking ' + tn });
        return { status: 200, body: updated };
      }
  deliver_order:
    method: POST
    path: /orders/{id}/deliver
    description: Mark a shipped order as delivered.
    input: {}
    handler: |-
      (ctx) => {
        const id = ctx.params.id;
        const o = ctx.db.get('order', id);
        if (o === null) ctx.fail(404, 'not_found', 'order ' + id + ' not found');
        if (o.status !== 'shipped') ctx.fail(409, 'invalid_state', 'order ' + id + ' is ' + o.status + '. Only shipped orders can be delivered.');
        const updated = ctx.db.update('order', id, { status: 'delivered', delivered_at: ctx.now() });
        ctx.db.create('order_event', { order_id: id, kind: 'delivered', note: null });
        return { status: 200, body: updated };
      }
  cancel_order:
    method: POST
    path: /orders/{id}/cancel
    description: Cancel a pending or paid order with a reason.
    input:
      reason:
        type: text
        description: Why the order is cancelled.
        required: true
        nullable: false
        unique: false
        readonly: false
    handler: |-
      (ctx) => {
        const id = ctx.params.id;
        const o = ctx.db.get('order', id);
        if (o === null) ctx.fail(404, 'not_found', 'order ' + id + ' not found');
        if (o.status !== 'pending' && o.status !== 'paid') ctx.fail(409, 'invalid_state', 'order ' + id + ' is ' + o.status + '. Only pending or paid orders can be cancelled.');
        const reason = ctx.body.reason.trim();
        if (reason === '') ctx.fail(400, 'input.invalid', 'Invalid input for cancel_order: reason expected a non-blank text, found ""');
        const updated = ctx.db.update('order', id, { status: 'cancelled', cancelled_at: ctx.now() });
        ctx.db.create('order_event', { order_id: id, kind: 'cancelled', note: reason });
        return { status: 200, body: updated };
      }
  refund_order:
    method: POST
    path: /orders/{id}/refund
    description: Fully refund a paid, shipped or delivered order with a reason.
    input:
      reason:
        type: text
        description: Why the order is refunded.
        required: true
        nullable: false
        unique: false
        readonly: false
    handler: |-
      (ctx) => {
        const id = ctx.params.id;
        const o = ctx.db.get('order', id);
        if (o === null) ctx.fail(404, 'not_found', 'order ' + id + ' not found');
        if (o.status !== 'paid' && o.status !== 'shipped' && o.status !== 'delivered') ctx.fail(409, 'invalid_state', 'order ' + id + ' is ' + o.status + '. Only paid, shipped or delivered orders can be refunded.');
        const reason = ctx.body.reason.trim();
        if (reason === '') ctx.fail(400, 'input.invalid', 'Invalid input for refund_order: reason expected a non-blank text, found ""');
        const updated = ctx.db.update('order', id, { status: 'refunded', refunded_at: ctx.now() });
        ctx.db.create('order_event', { order_id: id, kind: 'refunded', note: reason });
        return { status: 200, body: updated };
      }
jobs:
  auto_cancel_unpaid:
    description: Every hour, cancel pending orders placed 72 hours or more ago.
    every: 1h
    run: |-
      (ctx) => {
        const now = ctx.now();
        for (const o of ctx.db.list('order', { where: { status: 'pending' } })) {
          if (ctx.time.minutesBetween(o.placed_at, now) < 72 * 60) continue;
          ctx.db.update('order', o.id, { status: 'cancelled', cancelled_at: now });
          ctx.db.create('order_event', { order_id: o.id, kind: 'cancelled', note: 'auto: unpaid for 72h' });
        }
      }
