(ctx) => {
  const out = [];
  const reasons = ['Customer changed their mind', 'Out of stock', 'Duplicate order'];
  const refundReasons = ['Arrived damaged', 'Duplicate charge', 'Customer returned item'];
  let n = 0;
  for (const o of ctx.rows('order')) {
    const ev = [];
    const paidAt = ctx.time.plus(o.placed_at, '1h');
    if (o.status === 'paid') ev.push({ kind: 'paid', note: null, at: paidAt });
    if (o.status === 'shipped') { ev.push({ kind: 'paid', note: null, at: paidAt }); ev.push({ kind: 'shipped', note: 'tracking ' + o.tracking_number, at: o.shipped_at }); }
    if (o.status === 'delivered') { ev.push({ kind: 'paid', note: null, at: paidAt }); ev.push({ kind: 'shipped', note: 'tracking ' + o.tracking_number, at: o.shipped_at }); ev.push({ kind: 'delivered', note: null, at: o.delivered_at }); }
    if (o.status === 'cancelled') ev.push({ kind: 'cancelled', note: reasons[n % 3], at: o.cancelled_at });
    if (o.status === 'refunded') { ev.push({ kind: 'paid', note: null, at: paidAt }); ev.push({ kind: 'shipped', note: 'tracking ' + o.tracking_number, at: o.shipped_at }); ev.push({ kind: 'refunded', note: refundReasons[n % 3], at: o.refunded_at }); }
    if (ev.length === 0 || out.length + ev.length > 60) continue;
    n++;
    for (const e of ev) out.push({ at: e.at, row: { order_id: o.id, kind: e.kind, note: e.note } });
  }
  out.sort((a, b) => (a.at < b.at ? -1 : a.at > b.at ? 1 : 0));
  return out.map((e) => ({ ...e.row, created_at: e.at, updated_at: e.at }));
}
